WITH metrics AS (SELECT *, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_budget, MAX(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_budget, MIN(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_budget, AVG(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_budget, NTILE(5) OVER (PARTITION BY location ORDER BY budget DESC, id) AS budget_bucket FROM departments WHERE location IN ('Bangkok', 'Singapore', 'Chiang Mai')), enriched AS (SELECT *, LAG(running_sum_budget) OVER w_hist AS prev_running_sum_budget, LEAD(budget) OVER w_hist AS next_budget, LAG(budget) OVER w_hist AS prev_budget, ROW_NUMBER() OVER w_hist AS seq_no, CUME_DIST() OVER w_grp AS running_min_budget_cume_dist FROM metrics WINDOW w_hist AS (PARTITION BY location, dept_name ORDER BY running_max_budget, id), w_grp AS (ORDER BY running_min_budget NULLS LAST)), cleaned AS (SELECT *, ROUND(budget_bucket * 1.1, 2) AS budget_bucket_adjusted FROM enriched WHERE dept_name IS NOT NULL), ranked AS (SELECT id, dept_name, location, budget, running_sum_budget, budget_bucket, next_budget, prev_budget, seq_no, running_min_budget_cume_dist FROM cleaned QUALIFY ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget DESC, id) = 1) SELECT CASE WHEN budget >= 4239000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, SUM(CASE WHEN location = 'London' THEN budget_bucket ELSE 0 END) AS london_budget_bucket, APPROX_PERCENTILE(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, COUNT(*) FILTER (WHERE location = 'New York') AS new_york_rows, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list FROM ranked GROUP BY CASE WHEN budget >= 4239000 THEN 'LARGE' ELSE 'SMALL' END HAVING COUNT(*) FILTER (WHERE location = 'New York') > 1
